SELECT e.a, e.b, r.route_name, e.lane_class, e.length_px, r.edition, r.source_url, r.source_revision FROM e JOIN r ON r.i = e.i
ON CONFLICT (a, b, route_name) DO UPDATE SET lane_class = EXCLUDED.lane_class, length_px = EXCLUDED.length_px, edition = EXCLUDED.edition, source_url = EXCLUDED.source_url, source_revision = EXCLUDED.source_revision;

ON CONFLICT (system_id, note) DO UPDATE SET upgrades = EXCLUDED.upgrades;
